sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* Breadcrumbs */
.breadcrumbs {
  display: flex;
  flex-direction: row;
  align-items: center;
  font-weight: 400;
  height: 25px;
  gap: 8px;
  margin: 48px 0px;
}

.breadcrumbs a {
  color: blue;
}


.breadcrumbs__back {
  font-size: 16px;
  display: flex;
  flex-direction: row;
  gap: 8px;
  align-items: center;
}

.breadcrumbs__divider {
  border-left: 1px;
  border-right: 0px;
  border-style: solid;
  border-color: #E5E7EB;
  margin: 0 5px;
  height: 25px;
}

.breadcrumbs__pages {
	font-size: 18px;
}

.breadcrumbs__pages a + a::before {
  content: " / "; /* The text you want to insert */
  color: blue;
  font-weight: 400;
  font-size: 18px;
  margin: 0 5px;
}

.breadcrumbs__last {
  color: dark-gray !important;
  font-weight: 700;
  font-size: 22px;
  line-height: 35.2px;
  margin: 0px;
  pointer-events: none; /* Disables all pointer events */
  cursor: default;       /* Sets cursor to default instead of a pointer */
}

sp_widget.script:
function getPageTitle(pageID) {
    var page = new GlideRecord('sp_page');
    return page.get('id', pageID) ? page.getDisplayValue('title') : "Página";
}

function getParameterFromUrl(url, paramName) {
    var paramString = paramName + '=';
    var paramIndex = url.indexOf(paramString);

    if (paramIndex === -1) {
        paramIndex = url.indexOf('?' + paramString);
        if (paramIndex === -1) {
            paramIndex = url.indexOf('&' + paramString);
            if (paramIndex === -1) return null;
        }
    }

    var valueStartIndex = url.indexOf('=', paramIndex) + 1;
    var valueEndIndex = url.indexOf('&', valueStartIndex);

    return url.substring(valueStartIndex, valueEndIndex === -1 ? url.length : valueEndIndex);
}

function processDynamicParams(paramsParentStr, currentUrl, isCurrentPage) {
    if (!paramsParentStr || paramsParentStr === '') return '';

    var paramsParentObj = JSON.parse(paramsParentStr);
    var parentParamsUrl = '';

    for (var paramParent in paramsParentObj) {
        var parentValue = paramsParentObj[paramParent];

        // Verifica se é parâmetro dinâmico ${...}
        if (parentValue && parentValue.indexOf('${') !== -1 && parentValue.indexOf('}') !== -1) {
            parentValue = parentValue.toString();
            var dynamicParam = parentValue.substring(2, parentValue.length - 1);

            var paramValue = isCurrentPage ? $sp.getParameter(dynamicParam) : getParameterFromUrl(currentUrl, dynamicParam);

            if (paramValue) {
                parentParamsUrl += '&' + paramParent + '=' + paramValue;
            }
        } else {
            parentParamsUrl += '&' + paramParent + '=' + parentValue;
        }
    }

    return parentParamsUrl;
}

function processPageRecord(page, pages, defaultUrl, isCurrentPage) {
    pages[0].url = defaultUrl;
    var paramsFilterStr = page.getValue('parametros_caracteristicos');

    if (paramsFilterStr) {
        var paramsFilter = JSON.parse(paramsFilterStr);

        // Se é página atual, valida os parâmetros
        if (isCurrentPage) {
            var isValid = Object.keys(paramsFilter).every(function(param) {
                return $sp.getParameter(param) == paramsFilter[param];
            });

            if (!isValid) return false;
        }

        pages[0].title = page.getValue('descricao');

        for (var param in paramsFilter) {
            pages[0].url += '&' + param + '=' + paramsFilter[param];
        }
    }

    return true;
}

function getParentPage(pageId, pageSysID, pages, verifiedPages, parentParamsUrl) {
    // Evitar recursão infinita
    if (verifiedPages.indexOf(pageId.toString()) > -1) return pages;

    var defaultUrl = '?id=' + pageId + parentParamsUrl;

    pages.unshift({
        id: pageId,
        title: getPageTitle(pageId),
        url: defaultUrl
    });

    verifiedPages.push(pageId);

    var page = new GlideRecord('x_1083828_servic_0_breadcrumbs');
    page.addQuery('sys_id', pageSysID);
    page.query();

    if (page.next()) {
        var isCurrentPage = (pageId == $sp.getParameter('id'));

        // Processa o registro
        if (!processPageRecord(page, pages, defaultUrl, isCurrentPage)) {
            return pages;
        }

        // Processa página pai
        if (page.getValue('pagina_pai')) {
            var parentParamsUrl = processDynamicParams(
                page.getValue('parametros_da_pagina_pai'),
                pages[0].url,
                isCurrentPage
            );

            return getParentPage(
                page.pagina_pai.pagina.id.toString(),
                page.getValue('pagina_pai'),
                pages,
                verifiedPages,
                parentParamsUrl
            );
        }
    }

    return pages;
}

function getBreadcrumb(pageId) {
    var pages = [{
        id: pageId,
        title: getPageTitle(pageId),
        url: '?id=' + pageId
    }];

    var page = new GlideRecord('x_1083828_servic_0_breadcrumbs');
    page.addQuery('pagina.id', pageId);
    page.orderByDesc('quantidade_parametros_caracteristicos');
    page.query();

    while (page.next()) {
        var defaultUrl = '?id=' + pageId;
        var isCurrentPage = true;

        // Processa o registro
        if (!processPageRecord(page, pages, defaultUrl, isCurrentPage)) {
            continue;
        }

        // Processa página pai
        if (page.getValue('pagina_pai')) {
            var parentParamsUrl = processDynamicParams(
                page.getValue('parametros_da_pagina_pai'),
                pages[0].url,
                isCurrentPage
            );

            return getParentPage(
                page.pagina_pai.pagina.id.toString(),
                page.getValue('pagina_pai'),
                pages,
                [pageId],
                parentParamsUrl
            );
        }
    }

    return pages;
}

(function() {
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */

    data.urlSuffix = $sp.getValue('url_suffix');
    const portalRecord = $sp.getPortalRecord();

    data.homepageTitle = portalRecord.homepage.title.getDisplayValue();

    var currentPage = $sp.getParameter('id');

    data.parentPages = getBreadcrumb(currentPage);
    data.backButtonHref = ''; // Por padrão redirecionar para página inicial do portal

    if (data.parentPages.length > 1) { // Se houver página pai, redirecionar para ela
        data.backButtonHref = '?id=' + data.parentPages[data.parentPages.length - 2].id;
    }

})();
